import { mkdir, readFile, readdir, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const REPO_ROOT = fileURLToPath(new URL('..', import.meta.url));
const MANIFEST_FILENAME = 'index.json';
const YAML_EXTENSION = '.yml';

const GENERATED_HEADER = [
	'// This file is generated by scripts/generate-source-file-lists.mjs.',
	'// Do not edit it manually: run "npm run generate:source-files" to regenerate.',
].join('\n');

const SOURCE_GROUPS = [
	{
		name: 'cards',
		directory: 'static/docs/cards',
		assetPrefix: '/docs/cards',
		exportName: 'CARD_SOURCE_FILES',
		outputFile: 'src/lib/generated/card-source-files.ts',
	},
	{
		name: 'bestiary',
		directory: 'static/docs/bestiary',
		assetPrefix: '/docs/bestiary',
		exportName: 'BESTIARY_SOURCE_FILES',
		outputFile: 'src/lib/generated/bestiary-source-files.ts',
	},
];

const isYamlFile = (entry) => entry.isFile() && entry.name.endsWith(YAML_EXTENSION);

const listYamlFilenames = async (directory) => {
	const entries = await readdir(directory, { withFileTypes: true });
	return entries.filter(isYamlFile).map((entry) => entry.name);
};

const readManifestFilenames = async (directory) => {
	const manifestPath = path.join(directory, MANIFEST_FILENAME);

	let parsed;
	try {
		parsed = JSON.parse(await readFile(manifestPath, 'utf8'));
	} catch (error) {
		throw new Error(`Unable to read manifest ${manifestPath}: ${error.message}`);
	}

	const files = parsed?.files;
	if (!Array.isArray(files) || !files.every((file) => typeof file === 'string')) {
		throw new Error(`Manifest ${manifestPath} must contain a "files" string array`);
	}
	return files;
};

const validateCorpus = ({ corpusName, manifestFilenames, yamlFilenames }) => {
	const problems = [];
	const manifestSet = new Set(manifestFilenames);
	const yamlSet = new Set(yamlFilenames);

	const nonYamlManifestEntries = manifestFilenames.filter(
		(filename) => !filename.endsWith(YAML_EXTENSION),
	);
	if (nonYamlManifestEntries.length > 0) {
		problems.push(`non-YAML manifest entries: ${nonYamlManifestEntries.join(', ')}`);
	}

	const duplicateManifestEntries = manifestFilenames.filter(
		(filename, index) => manifestFilenames.indexOf(filename) !== index,
	);
	if (duplicateManifestEntries.length > 0) {
		problems.push(`duplicated manifest entries: ${duplicateManifestEntries.join(', ')}`);
	}

	const staleManifestEntries = manifestFilenames.filter((filename) => !yamlSet.has(filename));
	if (staleManifestEntries.length > 0) {
		problems.push(`manifest entries missing on disk: ${staleManifestEntries.join(', ')}`);
	}

	const unregisteredYamlFiles = yamlFilenames.filter((filename) => !manifestSet.has(filename));
	if (unregisteredYamlFiles.length > 0) {
		problems.push(`YAML files not listed in manifest: ${unregisteredYamlFiles.join(', ')}`);
	}

	if (problems.length > 0) {
		throw new Error(`Corpus "${corpusName}" is out of sync:\n- ${problems.join('\n- ')}`);
	}
};

const renderModule = (exportName, assetPaths) => {
	const entries = assetPaths.map((assetPath) => `\t'${assetPath}',`).join('\n');
	return `${GENERATED_HEADER}\n\nexport const ${exportName} = [\n${entries}\n] as const;\n`;
};

const writeGeneratedModule = async (outputFile, content) => {
	const outputPath = path.join(REPO_ROOT, outputFile);
	await mkdir(path.dirname(outputPath), { recursive: true });
	await writeFile(outputPath, content, 'utf8');
};

const generateSourceList = async (group) => {
	const directory = path.join(REPO_ROOT, group.directory);
	const yamlFilenames = await listYamlFilenames(directory);
	const manifestFilenames = await readManifestFilenames(directory);

	validateCorpus({ corpusName: group.name, manifestFilenames, yamlFilenames });

	const assetPaths = manifestFilenames.map((filename) => `${group.assetPrefix}/${filename}`);
	await writeGeneratedModule(group.outputFile, renderModule(group.exportName, assetPaths));
	console.log(`Generated ${group.outputFile} with ${assetPaths.length} YAML entries`);
};

const main = async () => {
	for (const group of SOURCE_GROUPS) {
		await generateSourceList(group);
	}
};

main().catch((error) => {
	console.error(`generate-source-file-lists failed: ${error.message}`);
	process.exitCode = 1;
});
